1	'use client'
2	
3	import { useRouter, useSearchParams, usePathname } from 'next/navigation'
4	import { useTransition, useState } from 'react'
5	import { toast } from 'sonner'
6	import { cn } from '@/lib/utils'
7	
8	export type CodeFilter = 'all' | 'active' | 'expired' | 'fully_used'
9	
10	const FILTER_LABELS: Record<CodeFilter, string> = {
11	  all: 'All',
12	  active: 'Active',
13	  expired: 'Expired',
14	  fully_used: 'Fully used',
15	}
16	
17	const FILTERS: CodeFilter[] = ['all', 'active', 'expired', 'fully_used']
18	
19	interface CodesListFiltersProps {
20	  /** IDs of currently displayed codes for multi-select */
21	  codeIds: string[]
22	  onDeactivated?: () => void
23	}
24	
25	export function CodesListFilters({ codeIds, onDeactivated }: CodesListFiltersProps) {
26	  const router = useRouter()
27	  const pathname = usePathname()
28	  const searchParams = useSearchParams()
29	  const [, startTransition] = useTransition()
30	
31	  const currentFilter = (searchParams.get('codes') as CodeFilter | null) ?? 'all'
32	
33	  const [selected, setSelected] = useState<Set<string>>(new Set())
34	  const [deactivating, setDeactivating] = useState(false)
35	
36	  function setFilter(f: CodeFilter) {
37	    const params = new URLSearchParams(searchParams.toString())
38	    if (f === 'all') {
39	      params.delete('codes')
40	    } else {
41	      params.set('codes', f)
42	    }
43	    startTransition(() => {
44	      router.replace(`${pathname}?${params.toString()}`, { scroll: false })
45	    })
46	    setSelected(new Set())
47	  }
48	
49	  function toggleSelect(id: string) {
50	    setSelected((prev) => {
51	      const next = new Set(prev)
52	      if (next.has(id)) {
53	        next.delete(id)
54	      } else {
55	        next.add(id)
56	      }
57	      return next
58	    })
59	  }
60	
61	  function toggleSelectAll() {
62	    if (selected.size === codeIds.length) {
63	      setSelected(new Set())
64	    } else {
65	      setSelected(new Set(codeIds))
66	    }
67	  }
68	
69	  async function handleBulkDeactivate() {
70	    if (selected.size === 0) return
71	    setDeactivating(true)
72	    try {
73	      const res = await fetch('/api/marketing/referrals/codes/bulk-deactivate', {
74	        method: 'PATCH',
75	        headers: { 'Content-Type': 'application/json' },
76	        body: JSON.stringify({ code_ids: Array.from(selected) }),
77	      })
78	
79	      if (!res.ok) {
80	        const raw: unknown = await res.json()
81	        const msg =
82	          raw &&
83	          typeof raw === 'object' &&
84	          'error' in raw &&
85	          typeof (raw as { error: unknown }).error === 'string'
86	            ? (raw as { error: string }).error
87	            : `Request failed: ${res.status}`
88	        throw new Error(msg)
89	      }
90	
91	      toast.success(`Deactivated ${selected.size} code${selected.size !== 1 ? 's' : ''}`)
92	      setSelected(new Set())
93	      onDeactivated?.()
94	      startTransition(() => router.refresh())
95	    } catch (err) {
96	      toast.error(err instanceof Error ? err.message : String(err))
97	    } finally {
98	      setDeactivating(false)
99	    }
100	  }
101	
102	  return (
103	    <div className="space-y-3">
104	      {/* Filter pills */}
105	      <div className="flex items-center gap-1.5 flex-wrap">
106	        {FILTERS.map((f) => (
107	          <button
108	            key={f}
109	            type="button"
110	            onClick={() => setFilter(f)}
111	            className={cn(
112	              'rounded-full border px-3 py-1 text-[11px] font-medium transition-colors',
113	              currentFilter === f
114	                ? 'border-foreground bg-foreground text-background'
115	                : 'border-border bg-transparent text-muted-foreground hover:text-foreground hover:border-foreground/50',
116	            )}
117	            aria-pressed={currentFilter === f}
118	          >
119	            {FILTER_LABELS[f]}
120	          </button>
121	        ))}
122	
123	        {/* Multi-select controls */}
124	        {codeIds.length > 0 && (
125	          <button
126	            type="button"
127	            onClick={toggleSelectAll}
128	            className="ml-2 text-[11px] text-muted-foreground hover:text-foreground underline underline-offset-2 transition-colors"
129	          >
130	            {selected.size === codeIds.length ? 'Deselect all' : 'Select all'}
131	          </button>
132	        )}
133	
134	        {selected.size > 0 && (
135	          <button
136	            type="button"
137	            disabled={deactivating}
138	            onClick={handleBulkDeactivate}
139	            className="ml-1 rounded border border-destructive/40 bg-destructive/5 px-2.5 py-1 text-[11px] font-medium text-destructive hover:bg-destructive/10 transition-colors disabled:opacity-50"
140	          >
141	            {deactivating
142	              ? 'Deactivating...'
143	              : `Deactivate ${selected.size} selected`}
144	          </button>
145	        )}
146	      </div>
147	
148	      {/* Expose toggle for parent rows — only rendered when codeIds are visible */}
149	      {codeIds.length > 0 && (
150	        <div className="hidden" aria-hidden="true" data-codes-select-context="true">
151	          {/* Row-level checkboxes are rendered by the parent list via selectedSet + toggleSelect */}
152	          {codeIds.map((id) => (
153	            <input
154	              key={id}
155	              type="checkbox"
156	              data-code-checkbox={id}
157	              checked={selected.has(id)}
158	              onChange={() => toggleSelect(id)}
159	              aria-label={`Select code ${id}`}
160	            />
161	          ))}
162	        </div>
163	      )}
164	
165	      {/* Export the selection state through a callback pattern */}
166	      <_CodesSelectBridge
167	        codeIds={codeIds}
168	        selected={selected}
169	        toggleSelect={toggleSelect}
170	      />
171	    </div>
172	  )
173	}
174	
175	/**
176	 * Internal bridge to expose checkbox state to sibling components via DOM data
177	 * attributes. This avoids prop-drilling through the server component boundary.
178	 *
179	 * For the M5 scope, the parent CodesList uses this component to read selection.
180	 */
181	function _CodesSelectBridge({
182	  codeIds,
183	  selected,
184	  toggleSelect,
185	}: {
186	  codeIds: string[]
187	  selected: Set<string>
188	  toggleSelect: (id: string) => void
189	}) {
190	  return (
191	    <div data-codes-selection={JSON.stringify(Array.from(selected))} className="sr-only" aria-hidden="true">
192	      {codeIds.map((id) => (
193	        <button key={id} type="button" onClick={() => toggleSelect(id)} aria-label={`toggle select ${id}`} />
194	      ))}
195	    </div>
196	  )
197	}
198	
199	/**
200	 * Exported hook for parent to apply the active filter to a list of codes.
201	 */
202	export function applyCodeFilter<
203	  T extends {
204	    is_active: boolean
205	    expires_at?: string | null
206	    uses_count: number
207	    max_uses: number | null
208	  },
209	>(codes: T[], filter: CodeFilter): T[] {
210	  const now = new Date()
211	  switch (filter) {
212	    case 'active':
213	      return codes.filter(
214	        (c) =>
215	          c.is_active &&
216	          (c.expires_at == null || new Date(c.expires_at) > now) &&
217	          (c.max_uses == null || c.uses_count < c.max_uses),
218	      )
219	    case 'expired':
220	      return codes.filter(
221	        (c) => c.expires_at != null && new Date(c.expires_at) <= now,
222	      )
223	    case 'fully_used':
224	      return codes.filter(
225	        (c) => c.max_uses != null && c.uses_count >= c.max_uses,
226	      )
227	    case 'all':
228	    default:
229	      return codes
230	  }
231	}
